<#
  09-add-template-system.ps1  (copy/paste safe)

  Adds a color/theme picker for pair sites:

    shared/templates.ts        - NEW FILE: 5 built-in themes (Neon
                                 Green default, Cyber Purple, Electric
                                 Blue, Crimson, Gold Rush). Each theme
                                 is a hue-rotate degree offset rather
                                 than dozens of individually recolored
                                 values - the existing UI is built
                                 around one hardcoded green accent
                                 (~142deg) used in ~50 places across
                                 inline styles and CSS, so rotating
                                 the whole page's rendered hue is far
                                 more robust than trying to recolor
                                 every single value by hand. True
                                 grays/black/white are unaffected by
                                 hue rotation, so only the accent
                                 shifts.
    server/routes.ts           - GET /api/templates (public list);
                                 POST /api/sites now validates
                                 templateId against the known list
    client/src/pages/home.tsx   - applies the site's chosen theme as
                                 a CSS hue-rotate filter
    client/src/pages/dashboard.tsx - Site Builder now shows a row of
                                 clickable color swatches to pick a
                                 theme, and My Sites shows each site's
                                 theme as a small dot next to its name

  Every file is embedded as base64 (no quote characters in the
  payload), so this survives copy/paste through editors that convert
  straight quotes to curly "smart quotes".

  Run from an elevated (Run as Administrator) PowerShell prompt,
  from inside the project (project root or a subfolder):

      .\09-add-template-system.ps1

  Safe to re-run: each file is skipped individually if it already
  contains that file's marker.
#>

$ErrorActionPreference = "Stop"

function Find-ProjectRoot {
    $candidates = @(
        $PSScriptRoot,
        (Join-Path $PSScriptRoot ".."),
        (Get-Location).Path
    )
    foreach ($c in $candidates) {
        $pkg = Join-Path $c "package.json"
        if (Test-Path $pkg) {
            return (Resolve-Path $c).Path
        }
    }
    return $null
}

$projectRoot = Find-ProjectRoot
if (-not $projectRoot) {
    Write-Error "Could not find package.json near this script or the current directory. Run this script from inside your pairwolf-site project."
    exit 1
}
Write-Host "Project root: $projectRoot"

$files = @(
    [PSCustomObject]@{ RelPath = "shared\templates.ts"; Marker = "SITE_TEMPLATES"; B64 = "" },
    [PSCustomObject]@{ RelPath = "server\routes.ts"; Marker = "/api/templates"; B64 = "" },
    [PSCustomObject]@{ RelPath = "client\src\pages\home.tsx"; Marker = "hueRotate"; B64 = "" },
    [PSCustomObject]@{ RelPath = "client\src\pages\dashboard.tsx"; Marker = "button-template-"; B64 = "" }
)

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$anyApplied = $false
$anySkipped = $false
$anyFailed = $false

foreach ($f in $files) {
    $targetPath = Join-Path $projectRoot $f.RelPath
    $exists = Test-Path $targetPath

    if ($exists) {
        $existing = Get-Content -Raw -Path $targetPath
        if ($existing.Contains($f.Marker)) {
            Write-Host "SKIP  $($f.RelPath) (already up to date)" -ForegroundColor Yellow
            $anySkipped = $true
            continue
        }
        Copy-Item -Path $targetPath -Destination "$targetPath.bak" -Force
    } else {
        $parentDir = Split-Path -Parent $targetPath
        if (-not (Test-Path $parentDir)) {
            New-Item -ItemType Directory -Path $parentDir -Force | Out-Null
        }
    }

    try {
        $bytes = [System.Convert]::FromBase64String($f.B64)
        $newContent = [System.Text.Encoding]::UTF8.GetString($bytes)
        if (-not $newContent.Contains($f.Marker)) {
            Write-Host "FAIL  $($f.RelPath): decoded payload missing expected marker - skipped, no changes made. Re-download the script rather than retyping it." -ForegroundColor Red
            $anyFailed = $true
            continue
        }
        [System.IO.File]::WriteAllText($targetPath, $newContent, $utf8NoBom)
        Write-Host "OK    $($f.RelPath)" -ForegroundColor Green
        $anyApplied = $true
    } catch {
        Write-Host "FAIL  $($f.RelPath): $($_.Exception.Message)" -ForegroundColor Red
        $anyFailed = $true
    }
}

Write-Host ""
if ($anyFailed) {
    Write-Host "Some files failed - check the FAIL lines above before continuing." -ForegroundColor Red
    exit 1
}
if ($anyApplied) {
    Write-Host "Template system applied. Next steps:" -ForegroundColor Cyan
    Write-Host "  1. npm run check     (type-check)"
    Write-Host "  2. npm run dev       (start the server)"
    Write-Host "  3. curl http://localhost:5000/api/templates  -> should list 5 themes"
    Write-Host "  4. In the dashboard Create Site tab, pick a color swatch before creating a site"
} elseif ($anySkipped) {
    Write-Host "Everything was already up to date - nothing to do." -ForegroundColor Yellow
}